exemples.exemple:
PREFIX cine: <http://example.org/cinema/vocab#>
SELECT ?film ?annee
WHERE {
  ?film a cine:Film ;
        cine:annee ?annee .
}
ORDER BY ?annee

PREFIX cine: <http://example.org/cinema/vocab#>
SELECT ?titre
WHERE {
  ?film cine:titre ?titre .
  FILTER (lang(?titre) = "fr")
}

PREFIX cine: <http://example.org/cinema/vocab#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
PREFIX ex:   <http://example.org/cinema/>
SELECT ?nom ?personnage
WHERE {
  ?role cine:film ex:cleopatre ;
        cine:acteur ?acteur ;
        cine:personnage ?personnage .
  ?acteur foaf:name ?nom .
}

PREFIX cine: <http://example.org/cinema/vocab#>
SELECT ?film ?anglais
WHERE {
  ?film a cine:Film .
  OPTIONAL { ?film cine:titre ?anglais . FILTER (lang(?anglais) = "en") }
}

PREFIX cine: <http://example.org/cinema/vocab#>
SELECT ?film
WHERE {
  ?film a cine:Film .
  FILTER NOT EXISTS { ?p a cine:Projection ; cine:film ?film }
}

PREFIX rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
SELECT DISTINCT ?nom
WHERE {
  ?p rdf:type/rdfs:subClassOf* foaf:Person ;
     foaf:name ?nom .
}
ORDER BY ?nom

PREFIX cine: <http://example.org/cinema/vocab#>
PREFIX ex:   <http://example.org/cinema/>
INSERT DATA {
  ex:taxi a cine:Film ;
          cine:titre "Taxi"@fr ;
          cine:annee 1998 ;
          cine:genre "Comédie" .
}

PREFIX cine: <http://example.org/cinema/vocab#>
CONSTRUCT { ?acteur cine:aJoueDans ?film }
WHERE { ?role cine:acteur ?acteur ; cine:film ?film }
